    W = draw(st.integers(2, 5))
    small = draw(st.booleans())
    if small:
        vals = st.integers(1, 3)
    else:
        vals = st.integers(1, 10**9)
    A = [[draw(vals) for _ in range(W)] for _ in range(H)]
    p = draw(st.permutations(list(range(H))))
    q = draw(st.permutations(list(range(W))))
    B = [[A[p[i]][q[j]] for j in range(W)] for i in range(H)]
    if draw(st.integers(0, 3)) == 0:
        # perturb one cell so the answer is often -1
        i = draw(st.integers(0, H - 1))
        j = draw(st.integers(0, W - 1))
        B[i][j] = draw(vals)
    lines = [f"{H} {W}"]
    for row in A:
        lines.append(" ".join(map(str, row)))
    for row in B:
        lines.append(" ".join(map(str, row)))
    return "\n".join(lines) + "\n"


