    t = list(map(int, inp.split()))
    H, W = t[0], t[1]
    vals = t[2:]
    A = [vals[i * W:(i + 1) * W] for i in range(H)]
    off = H * W
    B = [vals[off + i * W: off + (i + 1) * W] for i in range(H)]
    return H, W, A, B


