    H, W, A, B = _parse(inp)
    best = None
    # Row permutation p and column permutation q: final A'[i][j] = A[p[i]][q[j]].
    # Minimal adjacent swaps to realise a permutation = its inversion count.
    # Row and column operations commute, so total cost = inv(p) + inv(q).
